object Solution {
  def maxStudents(seats: Array[Array[Char]]): Int = {
    val m = seats.length
    val n = seats(0).length

    // For each row, create a bitmask representing which seats are available ('.')
    val validRows = seats.map { row =>
      var mask = 0
      for (j <- 0 until n) {
        if (row(j) == '.') mask |= (1 << j)
      }
      mask
    }

    // Precompute all valid seat arrangements for a row:
    // - no two students sit next to each other in the same row
    // - only sit in available seats
    // We'll generate all subsets of validRows(r) that have no adjacent bits set.
    def noAdjacentBits(x: Int): Boolean = (x & (x >> 1)) == 0

    val rowStates = Array.fill(m)(List.empty[Int])
    for (r <- 0 until m) {
      val valid = validRows(r)
      var states = List.empty[Int]
      // iterate over all subsets of valid
      var subset = valid
      while (true) {
        if (noAdjacentBits(subset)) states ::= subset
        if (subset == 0) {
          // done
          break
        }
        subset = (subset - 1) & valid
      }
      rowStates(r) = states
    }

    // DP: dp(r)(state) = max students seated from row 0 to r with row r in arrangement state
    // Transition:
    // For each state in row r, check all states in row r-1 that do not conflict diagonally:
    // No student in current row can peek at upper-left or upper-right:
    // That means:
    // For current state cur and previous state prev:
    // (cur << 1) & prev == 0 and (cur >> 1) & prev == 0
    import scala.collection.mutable

    val dp = Array.fill(m)(mutable.Map.empty[Int, Int])

    // Initialize dp for row 0
    for (state <- rowStates(0)) {
      dp(0)(state) = Integer.bitCount(state)
    }

    for (r <- 1 until m) {
      for (cur <- rowStates(r)) {
        val curCount = Integer.bitCount(cur)
        var maxPrev = 0
        for ((prev, prevCount) <- dp(r - 1)) {
          if (((cur << 1) & prev) == 0 && ((cur >> 1) & prev) == 0) {
            if (prevCount > maxPrev) maxPrev = prevCount
          }
        }
        if (maxPrev > 0 || r == 0) {
          dp(r)(cur) = maxPrev + curCount
        }
      }
    }

    // The answer is the max value in dp(m-1)
    if (m == 1) {
      dp(0).values.maxOption.getOrElse(0)
    } else {
      dp(m - 1).values.maxOption.getOrElse(0)
    }
  }
}

